import json
from collections import deque
import sys

def solve():
    houses = [1,2,3,4,5,6]

    categories = {
        "Name": ["Arnold", "Peter", "Bob", "Eric", "Carol", "Alice"],
        "Animal": ["horse", "rabbit", "fish", "cat", "bird", "dog"],
        "Occupation": ["engineer", "nurse", "lawyer", "teacher", "artist", "doctor"],
        "FavoriteSport": ["basketball", "volleyball", "soccer", "tennis", "baseball", "swimming"],
        "Height": ["average", "tall", "short", "very short", "very tall", "super tall"],
    }

    all_values = []
    value_to_category = {}
    for cat, vals in categories.items():
        for v in vals:
            all_values.append(v)
            value_to_category[v] = cat

    # Equality groups (must share the same house)
    equality_groups = [
        ["engineer","dog"],                   # 1
        ["teacher","horse","tennis"],         # 6 and 10
        ["Carol","soccer","fish"],            # 7 and 17
        ["average","swimming"],               # 11
        ["rabbit","Alice"],                   # 16
        ["tall","volleyball"],                # 8
        ["Arnold","cat"],                     # 5
        ["Peter","nurse"],                    # 13
    ]

    # Build equality map for quick lookup
    equals_map = {v: set([v]) for v in all_values}
    for group in equality_groups:
        group_set = set(group)
        for v in group:
            equals_map[v] = equals_map[v].union(group_set)

    # Directly-left constraints (X is immediately left of Y): X + 1 = Y
    direct_left = [
        ("average","rabbit"),    # 3
        ("baseball","engineer"), # 12
        ("teacher","soccer"),    # 15
    ]

    # Left-of constraints (X somewhere to the left of Y)
    left_of = [
        ("average","short"),         # 2
        ("tall","very short"),       # 4
        ("artist","Bob"),            # 14
        ("very short","cat"),        # 19 (cat right of very short)
    ]

    # Fixed positions
    fixed = {
        "lawyer": 5,        # 9
        "super tall": 5,    # 20
        "baseball": 1,      # 18
    }

    # Initialize domains
    domains = {v: set(houses) for v in all_values}
    # Apply fixed domains
    for v, pos in fixed.items():
        domains[v] = {pos}

    # Apply generic boundary pruning from direct-left and left-of
    for a,b in direct_left:
        # a cannot be at 6; b cannot be at 1
        domains[a] = domains[a].intersection(set([1,2,3,4,5]))
        domains[b] = domains[b].intersection(set([2,3,4,5,6]))
    for a,b in left_of:
        # a cannot be at 6; b cannot be at 1
        if 6 in domains[a]:
            domains[a].remove(6)
        if 1 in domains[b]:
            domains[b].remove(1)

    # Helper functions for propagation
    def copy_domains(d):
        return {k: set(v) for k,v in d.items()}

    def all_diff_propagate(d):
        changed = False
        # For each category, remove assigned positions from others
        for cat, vals in categories.items():
            singles = {v: next(iter(d[v])) for v in vals if len(d[v]) == 1}
            taken = set(singles.values())
            for v in vals:
                if len(d[v]) > 1:
                    before = set(d[v])
                    d[v] -= taken
                    if d[v] != before:
                        changed = True
                        if len(d[v]) == 0:
                            return None, True
        return d, changed

    def equal_groups_propagate(d):
        changed = False
        for group in equality_groups:
            inter = set(houses)
            for v in group:
                inter = inter.intersection(d[v])
            if len(inter) == 0:
                return None, True
            for v in group:
                before = set(d[v])
                newset = d[v].intersection(inter)
                if newset != before:
                    d[v] = newset
                    changed = True
                    if len(d[v]) == 0:
                        return None, True
        return d, changed

    def direct_left_arc(d):
        changed = False
        for a,b in direct_left:
            dom_a = d[a]
            dom_b = d[b]
            # Remove values from a that cannot be supported by b (p+1 must be in dom_b)
            remove_a = set()
            for p in dom_a:
                if p == 6 or (p+1) not in dom_b:
                    remove_a.add(p)
            if remove_a:
                new_a = dom_a - remove_a
                if len(new_a) == 0:
                    return None, True
                if new_a != dom_a:
                    d[a] = new_a
                    changed = True
            # Remove values from b that cannot be supported by a (q-1 must be in dom_a)
            remove_b = set()
            for q in dom_b:
                if q == 1 or (q-1) not in d[a]:
                    remove_b.add(q)
            if remove_b:
                new_b = dom_b - remove_b
                if len(new_b) == 0:
                    return None, True
                if new_b != dom_b:
                    d[b] = new_b
                    changed = True
        return d, changed

    def left_of_arc(d):
        changed = False
        for a,b in left_of:
            dom_a = d[a]
            dom_b = d[b]
            # A values must be < some value in dom_b
            if dom_b:
                max_b = max(dom_b)
                # remove a values >= max_b
                remove_a = {p for p in dom_a if p >= max_b}
                if remove_a:
                    new_a = dom_a - remove_a
                    if len(new_a) == 0:
                        return None, True
                    if new_a != dom_a:
                        d[a] = new_a
                        changed = True
            # B values must be > some value in dom_a
            if dom_a:
                min_a = min(dom_a)
                # remove b values <= min_a
                remove_b = {q for q in dom_b if q <= min_a}
                if remove_b:
                    new_b = dom_b - remove_b
                    if len(new_b) == 0:
                        return None, True
                    if new_b != dom_b:
                        d[b] = new_b
                        changed = True
        return d, changed

    def singleton_queue_propagate(d):
        # Process singletons to apply stronger propagation (equalities, all-different, adjacency immediate effects)
        queue = deque([v for v in all_values if len(d[v]) == 1])
        while queue:
            v = queue.popleft()
            if len(d[v]) != 1:
                continue
            pos_v = next(iter(d[v]))

            # Equalities: enforce same position
            for w in equals_map[v]:
                if w == v:
                    continue
                before = set(d[w])
                newset = d[w].intersection({pos_v})
                if newset != before:
                    d[w] = newset
                    if len(newset) == 0:
                        return None
                    if len(newset) == 1:
                        queue.append(w)

            # All-different within category
            cat = value_to_category[v]
            for u in categories[cat]:
                if u != v and pos_v in d[u]:
                    d[u].remove(pos_v)
                    if len(d[u]) == 0:
                        return None
                    if len(d[u]) == 1:
                        queue.append(u)

            # Direct-left constraints immediate narrowing
            for a,b in direct_left:
                if v == a:
                    # b must be pos_v +1
                    if pos_v == 6:
                        return None
                    before = set(d[b])
                    newset = d[b].intersection({pos_v+1})
                    if newset != before:
                        d[b] = newset
                        if len(newset) == 0:
                            return None
                        if len(newset) == 1:
                            queue.append(b)
                if v == b:
                    # a must be pos_v -1
                    if pos_v == 1:
                        return None
                    before = set(d[a])
                    newset = d[a].intersection({pos_v-1})
                    if newset != before:
                        d[a] = newset
                        if len(newset) == 0:
                            return None
                        if len(newset) == 1:
                            queue.append(a)

            # Left-of constraints immediate narrowing
            for a,b in left_of:
                if v == a:
                    # b must be > pos_v
                    before = set(d[b])
                    newset = {q for q in d[b] if q > pos_v}
                    if newset != before:
                        d[b] = newset
                        if len(newset) == 0:
                            return None
                        if len(newset) == 1:
                            queue.append(b)
                if v == b:
                    # a must be < pos_v
                    before = set(d[a])
                    newset = {p for p in d[a] if p < pos_v}
                    if newset != before:
                        d[a] = newset
                        if len(newset) == 0:
                            return None
                        if len(newset) == 1:
                            queue.append(a)
        return d

    def propagate(d):
        d = copy_domains(d)
        # Fixed domains have been set initially; now iterate constraints to a fixpoint
        while True:
            # First, handle equality group intersection
            d, ch1 = equal_groups_propagate(d)
            if d is None:
                return None
            # Arc consistency for direct-left
            d, ch2 = direct_left_arc(d)
            if d is None:
                return None
            # Arc consistency for left-of
            d, ch3 = left_of_arc(d)
            if d is None:
                return None
            # All-different after possible changes
            d, ch4 = all_diff_propagate(d)
            if d is None:
                return None
            # Process singletons queue to push implications
            d2 = singleton_queue_propagate(d)
            if d2 is None:
                return None
            d = d2
            # If no changes across phases, break
            if not (ch1 or ch2 or ch3 or ch4):
                break
        return d

    # Initial propagation
    domains = propagate(domains)
    if domains is None:
        raise ValueError("No solution under initial propagation.")

    # Backtracking search
    def is_complete(d):
        return all(len(d[v]) == 1 for v in all_values)

    def select_unassigned_var(d):
        # Minimum Remaining Values heuristic (skip singletons)
        candidates = [v for v in all_values if len(d[v]) > 1]
        # Tiebreaker: smaller domain first, then by category order to be stable
        if not candidates:
            return None
        candidates.sort(key=lambda x: (len(d[x]), list(categories.keys()).index(value_to_category[x])))
        return candidates[0]

    sys.setrecursionlimit(10000)

    def backtrack(d):
        d = propagate(d)
        if d is None:
            return None
        if is_complete(d):
            return d
        var = select_unassigned_var(d)
        if var is None:
            return None
        # Try values in sorted order for determinism
        for val in sorted(d[var]):
            new_d = copy_domains(d)
            new_d[var] = {val}
            new_d = propagate(new_d)
            if new_d is None:
                continue
            result = backtrack(new_d)
            if result is not None:
                return result
        return None

    solution_domains = backtrack(domains)
    if solution_domains is None:
        raise ValueError("No solution found.")

    # Build final assignment mapping var -> position
    assignment = {v: next(iter(solution_domains[v])) for v in all_values}

    # Build reverse maps per category: position -> value
    rev = {}
    for cat, vals in categories.items():
        rev_cat = {}
        for v in vals:
            rev_cat[assignment[v]] = v
        rev[cat] = rev_cat

    # Build rows
    header = ["House", "Name", "Animal", "Occupation", "FavoriteSport", "Height"]
    rows = []
    for i in range(1, 7):
        row = [
            str(i),
            rev["Name"][i],
            rev["Animal"][i],
            rev["Occupation"][i],
            rev["FavoriteSport"][i],
            rev["Height"][i],
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
